enum fetch_step
handle_backend_fetch_failure(struct worker *wrk, struct busyobj *bo)
{
	AN(wrk);
	AN(bo);

	wrk->stats.fetch_failure++;

	http_set_header(bo->bereq, "Backend-Response", "fetch-failed");
	http_set_header(bo->bereq, "X-Error", "Backend fetch failed");

	if (bo->objcore != NULL)
		bo->objcore->t_origin = W_TIMEDOUT(wrk);

	if (bo->waitinglist != NULL) {
		bo->objcore->grace += 1.0;
		bo->objcore->keep += 1.0;
	}

	ALLOC_OBJ(bo->http, HTTP_MAGIC);
	bo->http = http_copy(wrk, bo->http, bo->bereq);
	http_SetReason(bo->http, "Backend fetch failed");
	http_SetStatus(bo->http, 503);

	VCL_error(wrk, 503, "Backend fetch failed");

	if (wrk->handling == 0)
		return (F_STP_RETRY);
	else if (wrk->handling == 1)
		return (F_STP_DONE);
	else
		return (F_STP_FAIL);

	if (bo->objcore != NULL)
		oc_storage(bo->objcore, wrk, bo->http);

	return (F_STP_DONE);
}

enum fetch_step
handle_backend_fetch_failure(struct worker *wrk, struct busyobj *bo)
{
	AN(wrk);
	AN(bo);
	AN(bo->objcore);

	wrk->stats.fetch_fail++;

	VSLb(bo->vsl, SLT_FetchError, "Backend fetch failed");

	if (bo->http->{rx|tx}_hdrs)
		HTTP_Teardown(bo->http);

	bo->http->status = 502;
	bo->http->proto = 10;
	bo->http->conds = 0;
	bo->http->ws = WS_Copied(bo->ws);
	HTTP_PrintfHeader(bo->http, "Content-Type", "text/html");
	HTTP_PrintfHeader(bo->http, "Content-Length", "0");

	bo->do_esi = 0;
	bo->do_gunzip = 0;

	VCL_backend_error(wrk, bo);

	if (wrk->handling == HTTPEngine_Retry)
		return (F_STP_RETRY);
	else if (wrk->handling == HTTPEngine_Deliver)
		return (F_STP_DONE);
	else
		return (F_STP_FAIL);
}

